css:
:root{--own:#0090a8;--dim:#cdcdcf}
.own,.after{color:var(--own)} .own .bar,.after .bar{background:var(--own)}
.rival,.before{color:#9a9a9a} .rival .title{color:#7d7d7d;font-weight:700}
.rival .bar,.before .bar{background:var(--dim)}
/* 残りは塗らない（欠けにする） */
.ring{width:300px;aspect-ratio:1;border-radius:50%;position:relative;background:conic-gradient(#f07800 0 95.3%,#fff 95.3% 100%)}
.ring::after{content:'';position:absolute;inset:26px;border-radius:50%;background:#f7f4ee}
